import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.nkraVhM_.js";var i=JSON.parse(`{"title":"Einführung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/introduction.md","filePath":"de/guide/introduction.md","lastUpdated":1793173149000}`),a={name:`de/guide/introduction.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="einfuhrung" tabindex="-1">Einführung <a class="header-anchor" href="#einfuhrung" aria-label="Permalink to “Einführung”">​</a></h1><h2 id="uber-sudoku" tabindex="-1">Über Sudoku <a class="header-anchor" href="#uber-sudoku" aria-label="Permalink to “Über Sudoku”">​</a></h2><p><strong>Sudoku — Das klassische Zahlenrätsel, perfekt umgesetzt.</strong></p><p><img src="/screenshot-ipad-main.png" alt="Sudoku auf dem iPad"></p><p>Entdecken Sie das zeitlose Logikrätsel neu, das Sie lieben – für moderne Geräte verfeinert, mit flüssiger Bedienung, wunderschönen Designs und unendlichem Wiederspielwert. Ob Sie zum ersten Mal spielen oder ein erfahrener Experte sind: Dies ist das Sudoku-Erlebnis, auf das Sie gewartet haben.</p><h2 id="kernfunktionen" tabindex="-1">Kernfunktionen <a class="header-anchor" href="#kernfunktionen" aria-label="Permalink to “Kernfunktionen”">​</a></h2><h3 id="🔢-authentisches-spielgefuhl" tabindex="-1">🔢 <strong>Authentisches Spielgefühl</strong> <a class="header-anchor" href="#🔢-authentisches-spielgefuhl" aria-label="Permalink to “🔢 Authentisches Spielgefühl”">​</a></h3><p>Getreu den klassischen Regeln: Füllen Sie ein 9×9-Gitter so, dass jede Zeile, jede Spalte und jeder 3×3-Block die Ziffern 1 bis 9 genau einmal enthält. Tippen Sie, um Zahlen zu setzen, nutzen Sie Notizen für Kandidaten und lassen Sie sich von der Logik zur Lösung führen.</p><h3 id="🎯-5-schwierigkeitsgrade" tabindex="-1">🎯 <strong>5 Schwierigkeitsgrade</strong> <a class="header-anchor" href="#🎯-5-schwierigkeitsgrade" aria-label="Permalink to “🎯 5 Schwierigkeitsgrade”">​</a></h3><p>Fünf sorgfältig abgestufte Schwierigkeitsgrade mit unterschiedlich vielen vorgegebenen Feldern:</p><table tabindex="0"><thead><tr><th>Grad</th><th>Vorgegebene Felder</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Leicht</td><td>45</td><td>Ideal für Einsteiger und kurze Spielrunden</td></tr><tr><td>Mittel</td><td>36</td><td>Eine ausgewogene Herausforderung für Gelegenheitsspieler</td></tr><tr><td>Schwer</td><td>31</td><td>Erfordert logische Schlussfolgerungstechniken</td></tr><tr><td>Experte</td><td>27</td><td>Für erfahrene Löser, die eine echte Prüfung suchen</td></tr><tr><td>Meister</td><td>24</td><td>Die ultimative Herausforderung – nur für die Mutigsten</td></tr></tbody></table><p>Jedes Rätsel wird individuell erzeugt – zwei Partien sind nie identisch.</p><h3 id="📱-universelle-app" tabindex="-1">📱 <strong>Universelle App</strong> <a class="header-anchor" href="#📱-universelle-app" aria-label="Permalink to “📱 Universelle App”">​</a></h3><p>Ein Kauf gilt für iPhone, iPad und Mac. Native Bedienung auf jeder Plattform – Touch-Gesten unter iOS, Maus und Tastatur auf dem Mac. Ihr Fortschritt wird über iCloud auf allen Ihren Geräten synchronisiert.</p><p><img src="/screenshot-iphone-main.png" alt="Sudoku auf dem iPhone"></p><p><img src="/screenshot-mac-difficulty.png" alt="Sudoku auf dem Mac"></p><h3 id="💡-tipps-notizen" tabindex="-1">💡 <strong>Tipps &amp; Notizen</strong> <a class="header-anchor" href="#💡-tipps-notizen" aria-label="Permalink to “💡 Tipps &amp; Notizen”">​</a></h3><ul><li><strong>Tipp</strong>: Nicht weitergekommen? Ein Tipp deckt ein korrektes Feld auf, ohne das ganze Rätsel zu verraten.</li><li><strong>Notizen (Bleistift)</strong>: Aktivieren Sie den Notizmodus, um Kandidatenziffern in leere Felder zu schreiben. Notizen in benachbarten Feldern (gleiche Zeile, Spalte oder gleicher Block) werden automatisch gelöscht, sobald Sie eine Zahl setzen.</li><li><strong>Fehlerprüfung</strong>: Optionales Hervorheben falscher Eingaben, damit Sie aus Fehlern lernen können.</li><li><strong>Rückgängig</strong>: Vollständige Rückgängig-Funktion – nehmen Sie jeden Zug jederzeit zurück.</li></ul><h3 id="🏆-tagliche-herausforderung" tabindex="-1">🏆 <strong>Tägliche Herausforderung</strong> <a class="header-anchor" href="#🏆-tagliche-herausforderung" aria-label="Permalink to “🏆 Tägliche Herausforderung”">​</a></h3><p>Jeden Tag ein frisches Rätsel im Schwierigkeitsgrad Meister. Bauen Sie eine Serie auf und verfolgen Sie Ihren täglichen Fortschritt in der Kalenderansicht unter Statistiken.</p><h3 id="📊-statistiken" tabindex="-1">📊 <strong>Statistiken</strong> <a class="header-anchor" href="#📊-statistiken" aria-label="Permalink to “📊 Statistiken”">​</a></h3><p>Verfolgen Sie Ihre Leistung: gespielte Partien insgesamt, Gewinnquote, aktuelle Serie, beste Serie sowie Auswertungen je Schwierigkeitsgrad mit Bestzeiten und Durchschnittswerten. Synchronisiert über iCloud.</p><h3 id="🎨-8-wunderschone-designs" tabindex="-1">🎨 <strong>8 wunderschöne Designs</strong> <a class="header-anchor" href="#🎨-8-wunderschone-designs" aria-label="Permalink to “🎨 8 wunderschöne Designs”">​</a></h3><p>Personalisieren Sie Ihr Spielfeld mit acht handgefertigten Farbdesigns: Classic, Midnight, Paper, Forest, Ocean, Sunset, Lavender und Rose. Jedes Design bietet ein eigenständiges visuelles Erlebnis bei hervorragender Lesbarkeit.</p><h3 id="☁️-icloud-synchronisierung" tabindex="-1">☁️ <strong>iCloud-Synchronisierung</strong> <a class="header-anchor" href="#☁️-icloud-synchronisierung" aria-label="Permalink to “☁️ iCloud-Synchronisierung”">​</a></h3><p>Ihre Einstellungen, Statistiken, Spielstände und Fortschritte bei täglichen Herausforderungen werden über CloudKit automatisch auf allen Ihren Apple-Geräten synchronisiert. Beginnen Sie eine Partie auf dem iPhone und machen Sie auf dem Mac weiter.</p><h3 id="🎮-game-center" tabindex="-1">🎮 <strong>Game Center</strong> <a class="header-anchor" href="#🎮-game-center" aria-label="Permalink to “🎮 Game Center”">​</a></h3><p>Messen Sie sich in Ranglisten mit Ihren besten Lösungszeiten und sammeln Sie Erfolge: First Solve, Easy Clear, Medium Clear, Hard Clear, Expert Clear, Master Clear und Flawless (ohne Tipps oder Fehler abschließen).</p><h3 id="🔇-sauber-und-werbefrei" tabindex="-1">🔇 <strong>Sauber und werbefrei</strong> <a class="header-anchor" href="#🔇-sauber-und-werbefrei" aria-label="Permalink to “🔇 Sauber und werbefrei”">​</a></h3><p>Keine Unterbrechungen, keine Pop-ups, keine Werbung, keine In-App-Käufe. Nur pures, konzentriertes Rätselspiel.</p><h3 id="🌍-25-sprachen" tabindex="-1">🌍 <strong>25 Sprachen</strong> <a class="header-anchor" href="#🌍-25-sprachen" aria-label="Permalink to “🌍 25 Sprachen”">​</a></h3><p>Wechseln Sie die Sprache zur Laufzeit in den Einstellungen, ohne die App neu zu starten. Unterstützt werden Englisch, Chinesisch (vereinfacht und traditionell), Japanisch, Koreanisch, Französisch, Deutsch, Spanisch, Italienisch, Russisch, Portugiesisch, Niederländisch, Vietnamesisch, Thailändisch, Hindi, Türkisch, Griechisch, Finnisch, Norwegisch, Dänisch, Ungarisch, Indonesisch, Malaiisch, Ukrainisch und Deutsch (Schweiz).</p><h3 id="🔊-soundeffekte" tabindex="-1">🔊 <strong>Soundeffekte</strong> <a class="header-anchor" href="#🔊-soundeffekte" aria-label="Permalink to “🔊 Soundeffekte”">​</a></h3><p>Dezente Soundeffekte beim Setzen von Zahlen, bei Tipps, Fehlern und Siegen – in den Einstellungen ein- oder ausschaltbar.</p><h3 id="🖨️-ratsel-drucken" tabindex="-1">🖨️ <strong>Rätsel drucken</strong> <a class="header-anchor" href="#🖨️-ratsel-drucken" aria-label="Permalink to “🖨️ Rätsel drucken”">​</a></h3><p>Drucken Sie Rätsel direkt aus der Mac-App – mit Auswahl des Schwierigkeitsgrads und optionalen Lösungshinweisen. Ideal zum Lösen mit Stift und Papier.</p><h2 id="systemanforderungen" tabindex="-1">Systemanforderungen <a class="header-anchor" href="#systemanforderungen" aria-label="Permalink to “Systemanforderungen”">​</a></h2><ul><li><strong>iPhone/iPad</strong>: iOS/iPadOS 16.0 oder neuer</li><li><strong>Mac</strong>: macOS 15.0 (Sequoia) oder neuer (Apple Silicon)</li><li><strong>Speicherplatz</strong>: ca. 50 MB</li></ul><h2 id="datenschutz" tabindex="-1">Datenschutz <a class="header-anchor" href="#datenschutz" aria-label="Permalink to “Datenschutz”">​</a></h2><p>Sudoku ist beim Kernspiel offline-first. Alle Spieldaten werden lokal gespeichert und ausschließlich mit Ihrem persönlichen iCloud-Account synchronisiert. Keine Werbung, keine Analyse, kein Tracking durch Dritte. Die einzigen Netzwerkfunktionen sind die iCloud-Synchronisierung, Game Center und ein optionaler Bereich „Weitere Apps“ in den Einstellungen.</p><p>Details finden Sie in der <a href="/de/guide/privacy.html">Datenschutzerklärung</a>.</p><h2 id="erste-schritte" tabindex="-1">Erste Schritte <a class="header-anchor" href="#erste-schritte" aria-label="Permalink to “Erste Schritte”">​</a></h2><p>Wenn Sie neu bei Sudoku sind, beginnen Sie mit der <a href="/de/guide/installation.html">Installationsanleitung</a>, um die App auf Ihrem Gerät zu installieren.</p>`,43)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};